use std::rc::Rc;

// Ferris 與海鷗共用的寶物箱
struct Chest {
    items: Vec<String>,
}

// 放入寶物（重複就不放），回傳箱內數量
fn deposit(chest: &Rc<RefCell<Chest>>, item: &str) -> usize {
    let view = chest.borrow();
    if view.items.iter().any(|i| i.as_str() == item) {
        return view.items.len();
